SELECT 'датчик домена ' || fact_gap($1, 'domain-check') || ': есть ли лазейка в множестве — неизвестно' AS detail WHERE NOT fact_fresh($1, 'domain-check') UNION ALL SELECT f.name || '  —  ' || f.detail FROM code_fact f WHERE f.project_id = $1 AND f.kind = 'domain-check' AND f.detail LIKE 'лазейка разбора%' AND true ORDER BY 1
